// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "forge-std/Test.sol";
import "../src/Counter.sol";

contract CounterUnitTest is Test {
    Counter counter;
    address owner = address(this);
    address user = address(0x1);

    function setUp() public {
        counter = new Counter();
    }

    function test_increment() public {
        counter.increment();
        assertEq(counter.count(), 1);
    }

    function test_increment_multiple() public {
        counter.increment();
        counter.increment();
        counter.increment();
        assertEq(counter.count(), 3);
    }

    function test_decrement() public {
        counter.increment();
        counter.increment();
        counter.decrement();
        assertEq(counter.count(), 1);
    }

    function test_decrement_revertsAtZero() public {
        vm.expectRevert("Cannot go below zero");
        counter.decrement();
    }

    function test_reset_onlyOwner() public {
        counter.increment();
        counter.reset();
        assertEq(counter.count(), 0);
    }

    function test_reset_revertsIfNotOwner() public {
        counter.increment();
        vm.prank(user);
        vm.expectRevert("Not owner");
        counter.reset();
    }

    function test_owner_is_set() public {
        assertEq(counter.owner(), owner);
    }
}

