// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "forge-std/Test.sol";
import "../src/Counter.sol";

contract CounterIntegrationTest is Test {
    Counter counter;
    address alice = address(0xA);
    address bob = address(0xB);

    function setUp() public {
        counter = new Counter();
    }

    function test_multiUserFlow() public {
        vm.prank(alice);
        counter.increment();
        vm.prank(bob);
        counter.increment();
        vm.prank(alice);
        counter.increment();
        assertEq(counter.count(), 3);
    }

    function test_incrementThenReset() public {
        counter.increment();
        counter.increment();
        counter.reset();
        assertEq(counter.count(), 0);
    }

    function test_fullLifecycle() public {
        for (uint i = 0; i < 10; i++) {
            counter.increment();
        }
        assertEq(counter.count(), 10);
        counter.decrement();
        assertEq(counter.count(), 9);
        counter.reset();
        assertEq(counter.count(), 0);
    }
}

