// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "forge-std/Test.sol";
import "../src/Counter.sol";

contract CounterFuzzTest is Test {
    Counter counter;

    function setUp() public {
        counter = new Counter();
    }

    function testFuzz_incrementNeverUnderflows(uint8 n) public {
        for (uint i = 0; i < n; i++) {
            counter.increment();
        }
        assertTrue(counter.count() >= 0);
        assertEq(counter.count(), n);
    }

    function testFuzz_incrementDecrementBalance(uint8 incs, uint8 decs) public {
        vm.assume(decs <= incs);
        for (uint i = 0; i < incs; i++) counter.increment();
        for (uint i = 0; i < decs; i++) counter.decrement();
        assertEq(counter.count(), incs - decs);
    }
}

