// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "forge-std/Test.sol";
import "../src/Counter.sol";

contract CounterEdgeCaseTest is Test {
    Counter counter;

    function setUp() public {
        counter = new Counter();
    }

    function test_zeroState() public {
        assertEq(counter.count(), 0);
    }

    function test_resetOnZeroState() public {
        counter.reset();
        assertEq(counter.count(), 0);
    }

    function test_incrementFromZero() public {
        counter.increment();
        assertEq(counter.count(), 1);
    }

    function test_manyOperations() public {
        for (uint i = 0; i < 1000; i++) {
            counter.increment();
        }
        assertEq(counter.count(), 1000);
        for (uint i = 0; i < 1000; i++) {
            counter.decrement();
        }
        assertEq(counter.count(), 0);
    }
}

